
// Chakra Icons
import { BellIcon } from "@chakra-ui/icons";
// Chakra Imports
import {
  Box, Button,
  Flex,
  Menu,
  MenuButton,
  MenuItem,
  MenuList, Stack, Text, useColorMode,
  useColorModeValue
} from "@chakra-ui/react";
// Assets
import avatar1 from "assets/img/avatars/avatar1.png";
import avatar2 from "assets/img/avatars/avatar2.png";
import avatar3 from "assets/img/avatars/avatar3.png";
// Custom Icons
import { ProfileIcon, SettingsIcon } from "components/Icons/Icons";
import { FiLogOut } from "react-icons/fi";
import { useHistory } from "react-router-dom";
import { useState, useEffect } from "react";
import { Modal, ModalOverlay, ModalContent, ModalHeader, ModalBody, ModalFooter, ModalCloseButton, useDisclosure } from "@chakra-ui/react";
import NavbarLogo from "./NavbarLogo";
// Custom Components
import { ItemContent } from "components/Menu/ItemContent";
import { SearchBar } from "components/Navbars/SearchBar/SearchBar";
import { SidebarResponsive } from "components/Sidebar/Sidebar";
import React from "react";
import { NavLink } from "react-router-dom";
import routes from "routes.js";
import { collection, getDocs, query, orderBy, limit, where } from "firebase/firestore";
import { getAuth, onAuthStateChanged } from "firebase/auth";
import { firestore } from "../../firebase";

export default function HeaderLinks(props) {
  const {
    variant,
    children,
    fixed,
    scrolled,
    secondary,
    onOpen: parentOnOpen, // rename to avoid conflict
    ...rest
  } = props;

  const { colorMode } = useColorMode();
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const auth = getAuth();
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        const fetchNotifications = async () => {
          try {
            const notificationsCollection = collection(firestore, "notifications");
            const q = query(
              notificationsCollection,
              where("userId", "==", user.uid),
              orderBy("createdAt", "desc"),
              limit(5)
            );
            const querySnapshot = await getDocs(q);
            setNotifications(
              querySnapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }))
            );
          } catch (error) {
            console.error("Error fetching notifications:", error);
          }
        };
        fetchNotifications();
      } else {
        setNotifications([]);
      }
    });

    return () => unsubscribe();
  }, []);

  // Chakra Color Mode
  let navbarIcon =
    fixed && scrolled
      ? useColorModeValue("gray.700", "gray.200")
      : useColorModeValue("white", "gray.200");
  let menuBg = useColorModeValue("white", "navy.800");
  if (secondary) {
    navbarIcon = "white";
  }
  const history = useHistory();
  const { isOpen, onOpen, onClose } = useDisclosure();

  const handleLogout = () => {
    // Remove session and redirect to sign in
    localStorage.removeItem("user");
    onClose();
    setTimeout(() => {
      history.push("/auth/signin");
    }, 100);
  };

  return (
    <Flex
      pe={{ sm: "0px", md: "16px" }}
      w={{ sm: "100%", md: "auto" }}
      alignItems='center'
      flexDirection='row'>
      <SidebarResponsive
        hamburgerColor={"white"}
        logo={<NavbarLogo />}
        colorMode={colorMode}
        secondary={props.secondary}
        routes={routes}
        {...rest}
      />
      <Menu>
        <MenuButton>
          <BellIcon color={navbarIcon} w='18px' h='18px' />
        </MenuButton>
        <MenuList p='16px 8px' bg={menuBg}>
          <Flex flexDirection='column'>
            {notifications.map((notification) => (
              <MenuItem borderRadius='8px' mb='10px' key={notification.id}>
                <ItemContent
                  time={new Date(notification.createdAt?.toDate()).toLocaleTimeString()}
                  info={notification.message}
                  boldInfo={notification.title}
                />
              </MenuItem>
            ))}
            <MenuItem borderRadius='8px' onClick={() => history.push("/admin/notifications")}>
              <Text textAlign="center" w="100%">See all notifications</Text>
            </MenuItem>
          </Flex>
        </MenuList>
      </Menu>
      <Menu>
        <MenuButton as={Button} bg="transparent" _hover={{ bg: "transparent" }} _active={{ bg: "transparent" }}>
          <ProfileIcon color={navbarIcon} w='18px' h='18px' />
        </MenuButton>
        <MenuList bg={menuBg} minW="120px" maxW="150px" w="auto">
          <MenuItem onClick={() => history.push("/admin/profile")}>Profile</MenuItem>
          <MenuItem icon={<FiLogOut />} onClick={onOpen}>Logout</MenuItem>
        </MenuList>
      </Menu>
      {/* Removed separate logout button */}
      {/* Logout Confirmation Modal */}
      <Modal isOpen={isOpen} onClose={onClose} isCentered>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Confirm Logout</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            Are you sure you want to log out?
          </ModalBody>
          <ModalFooter>
            <Button colorScheme="orange" mr={3} onClick={handleLogout}>
              Yes, Logout
            </Button>
            <Button variant="ghost" onClick={onClose}>Cancel</Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Flex>
  );
}
